repo.visits.py:
"""Visit records."""


class Visit:
    def __init__(self, page, minutes):
        self.page = page
        self.minutes = minutes

    def __repr__(self):
        return "Visit(%r, %r)" % (self.page, self.minutes)


ROWS = [('docs', 33), ('blog', 56), ('home', 21), ('home', 18), ('docs', 19)]


def load_visits():
    """Yield the stored visits one at a time."""
    for page, minutes in ROWS:
        yield Visit(page, minutes)

repo.book.py:
"""A book of visits with a cached total."""


class VisitBook:
    def __init__(self):
        self._visits = []
        self._total = None

    def add(self, visit):
        """Add one visit to the book."""
        self._visits.append(visit)

    def total(self):
        """Return the total minutes of the visits in the book."""
        if self._total is None:
            self._total = sum(x.minutes for x in self._visits)
        return self._total

    def count(self):
        """Return how many visits the book holds."""
        return len(self._visits)

